package com.universalplatform.integration;
import com.universalplatform.audit.AuditService; import com.universalplatform.identity.*; import com.universalplatform.security.*; import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import java.time.Clock; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class FederationService { private final TenantContext tenants; private final ActorContext actor; private final AuthorizationService auth; private final IdentityProviderRepository repo; private final IntegrationSecretCipher cipher; private final AuditService audit; private final FederationIdentityDirectory federationIdentities; private final Clock clock=Clock.systemUTC(); FederationService(TenantContext t,ActorContext a,AuthorizationService z,IdentityProviderRepository r,IntegrationSecretCipher c,AuditService au,FederationIdentityDirectory fid){tenants=t;actor=a;auth=z;repo=r;cipher=c;audit=au;federationIdentities=fid;} @Transactional public ProviderView configure(String key,String issuer,String authEndpoint,String clientId,String clientSecret,String redirect,String scopes,long expectedVersion){auth.require(PermissionKey.FEDERATION_MANAGE);UUID t=tenants.requireTenantId();String k=required(key,64);String iss=uri(issuer,"issuer");String ae=uri(authEndpoint,"authorization endpoint");String ci=required(clientId,200);String rd=uri(redirect,"redirect URI");String sc=scopes==null||scopes.isBlank()?"openid profile email":scopes.trim();IdentityProvider p=repo.findByTenantIdAndProviderKey(t,k).orElse(null);Instant now=clock.instant();if(p!=null){if(p.version()!=expectedVersion)throw new IllegalArgumentException("Identity provider was modified by another request");p.update(iss,ae,ci,clientSecret==null||clientSecret.isBlank()?p.clientSecretCiphertext():cipher.encrypt(clientSecret),rd,sc,now);}else{if(expectedVersion!=0)throw new IllegalArgumentException("Identity provider version is stale");p=repo.save(new IdentityProvider(UUID.randomUUID(),t,k,iss,ae,ci,clientSecret==null?null:cipher.encrypt(clientSecret),rd,sc,now));}audit.record(t,actor.requireSubject(),"IDENTITY_PROVIDER_CONFIGURED","identity_provider",p.id().toString());return new ProviderView(p.id(),p.providerKey(),p.issuer(),p.authorizationEndpoint(),p.clientId(),p.redirectUri(),p.scopes(),p.version());}
 @Transactional(readOnly=true) public List<ProviderView> list(){auth.require(PermissionKey.FEDERATION_VIEW);return repo.findAllByTenantIdAndEnabledTrue(tenants.requireTenantId()).stream().map(p->new ProviderView(p.id(),p.providerKey(),p.issuer(),p.authorizationEndpoint(),p.clientId(),p.redirectUri(),p.scopes(),p.version())).toList();}
 @Transactional(readOnly=true) public String authorizationUrl(String key,String state,String nonce){auth.require(PermissionKey.FEDERATION_VIEW);if(state==null||state.isBlank()||nonce==null||nonce.isBlank())throw new IllegalArgumentException("State and nonce are required");IdentityProvider p=repo.findByTenantIdAndProviderKey(tenants.requireTenantId(),key).filter(IdentityProvider::enabled).orElseThrow(()->new IllegalArgumentException("Identity provider not found"));return p.authorizationEndpoint()+"?response_type=code&client_id="+enc(p.clientId())+"&redirect_uri="+enc(p.redirectUri())+"&scope="+enc(p.scopes())+"&state="+enc(state)+"&nonce="+enc(nonce);}

 @Transactional public FederationIdentityDirectory.SyncResult synchronize(String key,String subject,String email,String displayName,UUID primaryBranchId,String externalReference,Set<String> groups,Map<String,String> roleMappings,boolean active){auth.require(PermissionKey.FEDERATION_MANAGE);UUID t=tenants.requireTenantId();IdentityProvider p=repo.findByTenantIdAndProviderKey(t,required(key,64)).filter(IdentityProvider::enabled).orElseThrow(()->new IllegalArgumentException("Identity provider not found"));Map<String,SystemRoleKey> mapped=new LinkedHashMap<>();if(roleMappings!=null){for(var e:roleMappings.entrySet()){try{mapped.put(required(e.getKey(),160),SystemRoleKey.valueOf(required(e.getValue(),64)));}catch(IllegalArgumentException ex){throw new IllegalArgumentException("Invalid federated role mapping");}}}return federationIdentities.synchronize(p.providerKey(),subject,email,displayName,primaryBranchId,externalReference,groups,mapped,active);}
 private static String enc(String x){return URLEncoder.encode(x,StandardCharsets.UTF_8);} private static String required(String x,int max){if(x==null||x.isBlank()||x.trim().length()>max)throw new IllegalArgumentException("Invalid value");return x.trim();} private static String uri(String x,String label){try{java.net.URI u=java.net.URI.create(required(x,500));if(!Set.of("https","http").contains(u.getScheme())||u.getHost()==null)throw new IllegalArgumentException();return u.toString();}catch(Exception e){throw new IllegalArgumentException("Invalid "+label);}} public record ProviderView(UUID id,String providerKey,String issuer,String authorizationEndpoint,String clientId,String redirectUri,String scopes,long version){} }
